// Model of hsl.s and hsl.l per the claim. Reads triples of decimal strings from
// stdin (3 per line) and prints "s l" using the identical ostream formatting.
#include <iostream>
#include <string>
#include <algorithm>
#include <cmath>

static float cpp_max3(float r, float g, float b) {
    return std::max(std::max(r, g), b);
}
static float cpp_min3(float r, float g, float b) {
    return std::min(std::min(r, g), b);
}

int main(int argc, char** argv) {
    std::ios::sync_with_stdio(false);
    std::string a, b_, c;
    while (std::cin >> a >> b_ >> c) {
        float r = std::stof(a), g = std::stof(b_), b = std::stof(c);
        float mx = cpp_max3(r, g, b);
        float mn = cpp_min3(r, g, b);
        float delta = mx - mn;
        float l = (mx + mn) / 2.0f;
        float s;
        if (mx == mn) s = 0.0f;
        else if (l <= 0.5f) s = delta / (mx + mn);
        else s = delta / (2.0f - mx - mn);
        std::cout << s << " " << l << "\n";
    }
    std::cout.flush();
    return 0;
}

// Adversarial corpus generator for hsl.s / hsl.l.
// Prints one triple per line as %.9g decimal strings (round-trip exact for binary32),
// avoiding subnormals/overflow strings that std::stof rejects.
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <random>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

static inline float bits2f(uint32_t u) { float f; std::memcpy(&f, &u, 4); return f; }
static inline uint32_t f2bits(float f) { uint32_t u; std::memcpy(&u, &f, 4); return u; }

static bool cli_ok(float f) {
    // stof must not throw: reject subnormal-magnitude and non-finite handled separately
    if (std::isnan(f) || std::isinf(f)) return false; // handled by literal strings
    if (f == 0.0f) return true;
    float a = std::fabs(f);
    // %.9g of a value < ~1.2e-38 would underflow-ERANGE in strtof; keep safely above
    if (a < 1.5e-38f) return false;
    if (a > 3.0e38f) return false; // avoid overflow rounding on re-parse
    return true;
}

struct Out {
    std::vector<std::string> lines;
    std::set<std::string> seen;
    void add3(float r, float g, float b) {
        if (!cli_ok(r) || !cli_ok(g) || !cli_ok(b)) return;
        char buf[128];
        std::snprintf(buf, sizeof buf, "%.9g %.9g %.9g", r, g, b);
        std::string s(buf);
        if (seen.insert(s).second) lines.push_back(s);
    }
    void addRaw(const char* s) {
        std::string t(s);
        if (seen.insert(t).second) lines.push_back(t);
    }
};

int main(int argc, char** argv) {
    uint64_t seed = 0xC0FFEE1234567ULL;
    if (argc > 1) seed = std::strtoull(argv[1], nullptr, 10);
    std::mt19937_64 rng(seed);
    Out o;

    auto U = [&](double lo, double hi) {
        std::uniform_real_distribution<double> d(lo, hi);
        return (float)d(rng);
    };

    // ---- Family A: uniform random in [0,1]^3 (the "normal" domain)
    for (int i = 0; i < 40000; i++) o.add3(U(0,1), U(0,1), U(0,1));

    // ---- Family B: random with wide dynamic range / negatives
    for (int i = 0; i < 25000; i++) {
        auto rv = [&]() {
            int e = (int)(rng() % 60) - 30;      // 2^-30 .. 2^29
            double m = std::uniform_real_distribution<double>(0.5, 1.0)(rng);
            double v = m * std::pow(2.0, e);
            if (rng() & 1) v = -v;
            return (float)v;
        };
        o.add3(rv(), rv(), rv());
    }

    // ---- Family C: pairs whose FLOAT sum is EXACTLY 1.0f (l == 0.5 boundary),
    // with the third component in between so it doesn't change max/min.
    {
        int made = 0;
        for (uint64_t t = 0; made < 40000 && t < 4000000ULL; t++) {
            // pick max in [0.5, 1.0) then find min such that fl(max+min)==1.0f
            uint32_t lo = f2bits(0.5f), hi = f2bits(1.0f);
            uint32_t mb = lo + (uint32_t)(rng() % (hi - lo));
            float mx = bits2f(mb);
            float mn = 1.0f - mx; // exact by Sterbenz for mx in [0.5,1]
            if (!(mx + mn == 1.0f)) continue;
            float mid = mn + (mx - mn) * (float)std::uniform_real_distribution<double>(0,1)(rng);
            if (mid < mn) mid = mn; if (mid > mx) mid = mx;
            // permute so that max/min reduction still yields mx/mn
            int p = (int)(rng() % 6);
            float a3[3] = {mx, mn, mid};
            switch (p) {
                case 0: o.add3(mx, mn, mid); break;
                case 1: o.add3(mx, mid, mn); break;
                case 2: o.add3(mn, mx, mid); break;
                case 3: o.add3(mid, mx, mn); break;
                case 4: o.add3(mn, mid, mx); break;
                default: o.add3(mid, mn, mx); break;
            }
            (void)a3;
            made++;
        }
    }

    // ---- Family D: brute force arbitrary (mx,mn) pairs (not the 1-mx family)
    // whose float sum is exactly 1.0f, i.e. mn = nearest float such that sum rounds to 1.
    {
        int made = 0;
        for (uint64_t t = 0; made < 20000 && t < 8000000ULL; t++) {
            float mx = (float)std::uniform_real_distribution<double>(0.5, 4.0)(rng);
            // want fl(mx+mn)==1.0f -> mn approx 1-mx, then jitter by a few ulp
            float mn0 = (float)(1.0 - (double)mx);
            uint32_t mb = f2bits(mn0);
            int d = (int)(rng() % 9) - 4;
            uint32_t nb = (uint32_t)((int64_t)mb + d);
            float mn = bits2f(nb);
            if (!(mn < mx)) continue;
            if (mx + mn != 1.0f) continue;
            o.add3(mx, mn, mn);
            made++;
        }
    }

    // ---- Family E: near-boundary skirt: fl(max+min) within +-6 ulp of 1.0f
    {
        for (int i = 0; i < 30000; i++) {
            float mx = (float)std::uniform_real_distribution<double>(0.5, 1.0)(rng);
            float mn0 = 1.0f - mx;
            int d = (int)(rng() % 13) - 6;
            uint32_t nb = (uint32_t)((int64_t)f2bits(mn0) + d);
            float mn = bits2f(nb);
            if (mn > mx) continue;
            o.add3(mx, mn, mn);
        }
    }

    // ---- Family F: stride sweeps of the whole [0.5,1) ulp grid with min = 1-max
    {
        uint32_t lo = f2bits(0.5f), hi = f2bits(1.0f);
        for (uint32_t bb = lo; bb < hi; bb += 1009) {
            float mx = bits2f(bb);
            float mn = 1.0f - mx;
            o.add3(mx, mn, mn);
            o.add3(mn, mx, mn);
            // also 1-ulp perturbations
            o.add3(mx, bits2f(f2bits(mn)+1), bits2f(f2bits(mn)+1));
            o.add3(mx, bits2f(f2bits(mn)-1), bits2f(f2bits(mn)-1));
        }
    }

    // ---- Family G: max in [1,2) with negative min so that sum straddles 1.0
    {
        uint32_t lo = f2bits(1.0f), hi = f2bits(2.0f);
        for (uint32_t bb = lo; bb < hi; bb += 1511) {
            float mx = bits2f(bb);
            float mn = 1.0f - mx;   // negative, exact
            o.add3(mx, mn, mn);
            o.add3(mx, bits2f(f2bits(mn)+1), 0.0f);
            o.add3(mx, bits2f(f2bits(mn)-1), 0.0f);
        }
    }

    // ---- Family H: cases where 2.0f-mx-mn rounds (high branch) -- mx near 2, tiny mn
    {
        for (int i = 0; i < 20000; i++) {
            float mx = (float)std::uniform_real_distribution<double>(1.0, 2.0)(rng);
            int e = (int)(rng() % 40) - 35;
            float mn = (float)(std::pow(2.0, e) * std::uniform_real_distribution<double>(0.5,1.0)(rng));
            if (rng() & 1) mn = -mn;
            if (mn > mx) continue;
            o.add3(mx, mn, mn);
        }
    }

    // ---- Family I: mx,mn very close (tiny delta) -- catastrophic cancellation
    {
        for (int i = 0; i < 20000; i++) {
            float mx = (float)std::uniform_real_distribution<double>(-4.0, 4.0)(rng);
            int d = 1 + (int)(rng() % 2000);
            uint32_t nb = (uint32_t)((int64_t)f2bits(mx) - (mx >= 0 ? d : -d));
            float mn = bits2f(nb);
            if (mn > mx) std::swap(mx, mn);
            o.add3(mx, mn, mn);
            o.add3(mx, mx, mn);
            o.add3(mx, mn, mx);
        }
    }

    // ---- Family J: sums near 0 (low branch denominator near zero)
    {
        for (int i = 0; i < 15000; i++) {
            float mx = (float)std::uniform_real_distribution<double>(0.0, 4.0)(rng);
            float mn0 = -mx;
            int d = (int)(rng() % 21) - 10;
            uint32_t nb = (uint32_t)((int64_t)f2bits(mn0) + d);
            float mn = bits2f(nb);
            if (mn > mx) continue;
            o.add3(mx, mn, mn);
        }
    }

    // ---- Family K: quantized "8-bit-ish" and other human-scale values
    {
        for (int i = 0; i <= 255; i += 1)
          for (int j = 0; j <= 255; j += 37)
            for (int k = 0; k <= 255; k += 53)
                o.add3(i/255.0f, j/255.0f, k/255.0f);
    }

    // ---- Family L: exact special strings (non-finite, signed zeros)
    {
        const char* sp[] = {"0","-0","1","-1","inf","-inf","nan","-nan","0.5","2","-2",
                            "3.4e38","-3.4e38","1e30","-1e30","1e-30","-1e-30",
                            "1.17549435e-38","-1.17549435e-38"};
        int n = sizeof(sp)/sizeof(sp[0]);
        for (int i = 0; i < n; i++)
          for (int j = 0; j < n; j++)
            for (int k = 0; k < n; k++) {
                char buf[128];
                std::snprintf(buf, sizeof buf, "%s %s %s", sp[i], sp[j], sp[k]);
                o.addRaw(buf);
            }
    }

    // ---- Family M: mixed special + finite
    {
        const char* sp[] = {"inf","-inf","nan","-nan","-0","0"};
        for (int i = 0; i < 6; i++) {
            for (int t = 0; t < 400; t++) {
                float x = U(-3,3), y = U(-3,3);
                char b1[64], b2[64], buf[192];
                std::snprintf(b1, sizeof b1, "%.9g", x);
                std::snprintf(b2, sizeof b2, "%.9g", y);
                std::snprintf(buf, sizeof buf, "%s %s %s", sp[i], b1, b2); o.addRaw(buf);
                std::snprintf(buf, sizeof buf, "%s %s %s", b1, sp[i], b2); o.addRaw(buf);
                std::snprintf(buf, sizeof buf, "%s %s %s", b1, b2, sp[i]); o.addRaw(buf);
            }
        }
    }

    for (auto& s : o.lines) std::printf("%s\n", s.c_str());
    return 0;
}

// Multi-variant scorer: reads corpus (3 tokens/line) on stdin plus oracle s/l file,
// evaluates many candidate formulations, and reports mismatch counts + first witness.
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdio>

static float mx3(float r,float g,float b){return std::max(std::max(r,g),b);}
static float mn3(float r,float g,float b){return std::min(std::min(r,g),b);}

static std::string fmt(double v){ std::ostringstream o; o<<(float)v; return o.str(); }
static std::string fmtd(double v){ std::ostringstream o; o<<v; return o.str(); }

int main(int argc,char**argv){
    std::ios::sync_with_stdio(false);
    std::ifstream orc(argv[1]);
    struct V { const char* name; long bad=0; std::string first; };
    std::vector<V> S = {
      {"S0_claim"},{"S1_lt_strict"},{"S2_sum_lt1"},{"S3_dbl_l_le"},{"S4_dbl_l_lt"},
      {"S5_high_2m_sum"},{"S6_high_2mmin_max"},{"S7_high_1m1m"},{"S8_high_2m2l"},
      {"S9_high_dbl"},{"S10_low_dbl"},{"S11_delta_dbl"},{"S12_noguard"},
      {"S13_guard_delta0"},{"S14_low_2l"},{"S15_high_neg"},{"S16_branchless_min"},
      {"S17_high_2f_minus_max_minus_min_dbl2"},{"S18_low_sum_mul2l"},{"S19_all_double"},
      {"S20_sum_le1_dbl"},{"S21_high_fma"},{"S22_guard_maxeqmin_or_nan"},
    };
    std::vector<V> L = {
      {"L0_claim"},{"L1_half_add"},{"L2_dbl_then_float"},{"L3_double_field"},
      {"L4_min_plus_half_delta"},{"L5_mul_half"},{"L6_max_min_swap_order"},
    };
    std::string a,b_,c, os, ol;
    long n=0;
    while (std::cin>>a>>b_>>c) {
        if(!(orc>>os>>ol)) break;
        n++;
        float r=std::stof(a), g=std::stof(b_), b=std::stof(c);
        float mx=mx3(r,g,b), mn=mn3(r,g,b);
        float delta = mx-mn;
        float sum = mx+mn;
        float l = sum/2.0f;
        double dsum = (double)mx+(double)mn;
        double dl = dsum/2.0;
        float hiA = 2.0f-mx-mn;            // (2-max)-min
        float hiB = 2.0f-(mx+mn);
        float hiC = (2.0f-mn)-mx;
        float hiD = (1.0f-mx)+(1.0f-mn);
        float hiE = 2.0f-2.0f*l;
        float hiF = (float)(2.0-(double)mx-(double)mn);
        float hiG = -((mx+mn)-2.0f);
        bool guard = (mx==mn);
        bool lowf = (l<=0.5f);

        std::vector<std::string> sv(S.size()), lv(L.size());
        auto pick=[&](bool g_,bool low,float lowden,float hiden)->float{
            if(g_) return 0.0f; return low ? delta/lowden : delta/hiden; };
        sv[0]=fmt(pick(guard,lowf,sum,hiA));
        sv[1]=fmt(pick(guard,(l<0.5f),sum,hiA));
        sv[2]=fmt(pick(guard,(sum<1.0f),sum,hiA));
        sv[3]=fmt(pick(guard,(dl<=0.5),sum,hiA));
        sv[4]=fmt(pick(guard,(dl<0.5),sum,hiA));
        sv[5]=fmt(pick(guard,lowf,sum,hiB));
        sv[6]=fmt(pick(guard,lowf,sum,hiC));
        sv[7]=fmt(pick(guard,lowf,sum,hiD));
        sv[8]=fmt(pick(guard,lowf,sum,hiE));
        sv[9]=fmt(pick(guard,lowf,sum,hiF));
        sv[10]=guard?fmt(0.0f):fmt(lowf ? (double)delta/dsum : (double)delta/(double)hiA);
        { double dd=(double)mx-(double)mn;
          sv[11]=guard?fmt(0.0f):fmt(lowf ? (float)(dd/(double)sum) : (float)(dd/(double)hiA)); }
        sv[12]=fmt(lowf ? delta/sum : delta/hiA);
        sv[13]=fmt(pick((delta==0.0f),lowf,sum,hiA));
        sv[14]=fmt(pick(guard,lowf,2.0f*l,hiA));
        sv[15]=fmt(pick(guard,lowf,sum,hiG));
        { float den = std::min(sum,hiA); sv[16]=fmt(guard?0.0f:delta/den); }
        sv[17]=fmt(pick(guard,lowf,sum,(float)(2.0f-(double)mx-(double)mn)));
        sv[18]=fmt(pick(guard,lowf,2.0f*(sum/2.0f),hiA));
        { double ddelta=(double)mx-(double)mn;
          double dhi = 2.0-(double)mx-(double)mn;
          sv[19]=guard?fmtd(0.0):fmtd(dl<=0.5 ? ddelta/dsum : ddelta/dhi); }
        sv[20]=fmt(pick(guard,(dsum<=1.0),sum,hiA));
        { float den = std::fma(-2.0f,l,2.0f); sv[21]=fmt(pick(guard,lowf,sum,den)); }
        sv[22]=fmt(pick((mx==mn)||std::isnan(mx)||std::isnan(mn),lowf,sum,hiA));

        lv[0]=fmt(sum/2.0f);
        lv[1]=fmt(mx/2.0f+mn/2.0f);
        lv[2]=fmt((float)(dsum/2.0));
        lv[3]=fmtd(dsum/2.0);
        lv[4]=fmt(mn+delta/2.0f);
        lv[5]=fmt(sum*0.5f);
        lv[6]=fmt((mn+mx)/2.0f);

        for(size_t i=0;i<S.size();i++) if(sv[i]!=os){ if(!S[i].bad) S[i].first = a+" "+b_+" "+c+"  oracle="+os+" got="+sv[i]; S[i].bad++; }
        for(size_t i=0;i<L.size();i++) if(lv[i]!=ol){ if(!L[i].bad) L[i].first = a+" "+b_+" "+c+"  oracle="+ol+" got="+lv[i]; L[i].bad++; }
    }
    std::printf("N=%ld\n--- s variants ---\n", n);
    for(auto&v:S) std::printf("%-40s bad=%-8ld %s\n", v.name, v.bad, v.first.c_str());
    std::printf("--- l variants ---\n");
    for(auto&v:L) std::printf("%-40s bad=%-8ld %s\n", v.name, v.bad, v.first.c_str());
    return 0;
}

// Sieve generator: search random/structured triples, KEEP only those where the
// claimed formula's printed output differs from at least one plausible alternative,
// or where the claimed float result differs in print from the exact (long double) result.
// This maximizes 6th-significant-digit discriminating power per oracle invocation.
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <random>
#include <string>
#include <sstream>
#include <set>
#include <vector>
#include <algorithm>

static inline float bits2f(uint32_t u){float f;std::memcpy(&f,&u,4);return f;}
static inline uint32_t f2b(float f){uint32_t u;std::memcpy(&u,&f,4);return u;}
static float mx3(float r,float g,float b){return std::max(std::max(r,g),b);}
static float mn3(float r,float g,float b){return std::min(std::min(r,g),b);}
static std::string P(float v){std::ostringstream o;o<<v;return o.str();}
static std::string Pd(long double v){std::ostringstream o;o<<(double)v;return o.str();}

static bool cli_ok(float f){
    if(std::isnan(f)||std::isinf(f)) return false;
    if(f==0.0f) return true;
    float a=std::fabs(f);
    return a>=1.5e-38f && a<=3.0e38f;
}

// returns number of distinct printed s-values among the candidate set (>1 => discriminating)
static int discrimination(float r,float g,float b, std::string& claimS, std::string& claimL){
    float mx=mx3(r,g,b), mn=mn3(r,g,b);
    float delta=mx-mn, sum=mx+mn, l=sum/2.0f;
    long double lmx=mx,lmn=mn;
    long double lsum=lmx+lmn, ldelta=lmx-lmn;
    bool guard=(mx==mn);
    bool lowf=(l<=0.5f);
    float hiA=2.0f-mx-mn, hiB=2.0f-(mx+mn), hiC=(2.0f-mn)-mx,
          hiD=(1.0f-mx)+(1.0f-mn), hiE=2.0f-2.0f*l,
          hiF=(float)(2.0-(double)mx-(double)mn);
    std::set<std::string> ss, ll;
    auto add=[&](float v){ss.insert(P(v));};
    if(guard){ claimS=P(0.0f); }
    else claimS = P(lowf? delta/sum : delta/hiA);
    ss.insert(claimS);
    if(!guard){
        add((l<0.5f)? delta/sum : delta/hiA);
        add(((double)mx+(double)mn)/2.0<=0.5 ? delta/sum : delta/hiA);
        add(((double)mx+(double)mn)/2.0<0.5 ? delta/sum : delta/hiA);
        add(lowf? delta/sum : hiB==0?delta/hiB:delta/hiB);
        add(lowf? delta/sum : delta/hiC);
        add(lowf? delta/sum : delta/hiD);
        add(lowf? delta/sum : delta/hiE);
        add(lowf? delta/sum : delta/hiF);
        add(lowf? (float)((double)delta/((double)mx+(double)mn)) : (float)((double)delta/(double)hiA));
        add(lowf? (float)(((double)mx-(double)mn)/((double)mx+(double)mn)) : (float)(((double)mx-(double)mn)/((double)hiA)));
        // exact long double reference
        long double eS = (lsum/2.0L<=0.5L)? ldelta/lsum : ldelta/(2.0L-lmx-lmn);
        ss.insert(Pd(eS));
        // full double model
        double dS = ((double)mx+(double)mn)/2.0<=0.5 ? ((double)mx-(double)mn)/((double)mx+(double)mn)
                                                      : ((double)mx-(double)mn)/(2.0-(double)mx-(double)mn);
        std::ostringstream o;o<<dS;ss.insert(o.str());
    }
    claimL=P(l);
    ll.insert(claimL);
    ll.insert(P(mx/2.0f+mn/2.0f));
    ll.insert(P((float)(((double)mx+(double)mn)/2.0)));
    { std::ostringstream o;o<<(((double)mx+(double)mn)/2.0);ll.insert(o.str()); }
    ll.insert(P(mn+delta/2.0f));
    ll.insert(Pd(lsum/2.0L));
    return (int)ss.size() + (int)ll.size() - 2;
}

int main(int argc,char**argv){
    uint64_t seed = argc>1? std::strtoull(argv[1],nullptr,10) : 42;
    long want = argc>2? std::strtol(argv[2],nullptr,10) : 100000;
    std::mt19937_64 rng(seed);
    std::set<std::string> seen;
    std::vector<std::string> out;
    long tried=0;
    auto emit=[&](float r,float g,float b){
        if(!cli_ok(r)||!cli_ok(g)||!cli_ok(b)) return;
        std::string cs,cl;
        if(discrimination(r,g,b,cs,cl)<=0) return;
        char buf[160]; std::snprintf(buf,sizeof buf,"%.9g %.9g %.9g",r,g,b);
        std::string s(buf);
        if(seen.insert(s).second) out.push_back(s);
    };
    std::uniform_real_distribution<double> U01(0.0,1.0);
    while((long)out.size()<want && tried < 400000000L){
        tried++;
        int mode = (int)(rng()%10);
        float r,g,b;
        if(mode<3){ r=(float)U01(rng); g=(float)U01(rng); b=(float)U01(rng); }
        else if(mode<5){
            // near l==0.5 boundary
            float mx=(float)(0.5+0.5*U01(rng));
            float mn=1.0f-mx;
            int d=(int)(rng()%17)-8;
            mn=bits2f((uint32_t)((int64_t)f2b(mn)+d));
            float mid=mn+(mx-mn)*(float)U01(rng);
            r=mx;g=mn;b=mid;
            if(rng()&1) std::swap(r,g);
        } else if(mode<7){
            // wide dynamic range
            auto rv=[&](){int e=(int)(rng()%80)-40; double m=0.5+0.5*U01(rng); double v=m*std::pow(2.0,e); if(rng()&1)v=-v; return (float)v;};
            r=rv();g=rv();b=rv();
        } else if(mode<8){
            // max in [1,2), tiny/negative min => high branch with rounding
            float mx=(float)(1.0+U01(rng));
            int e=(int)(rng()%50)-45; float mn=(float)(std::pow(2.0,e)*(0.5+0.5*U01(rng)));
            if(rng()&1) mn=-mn;
            r=mx;g=mn;b=mn;
        } else if(mode<9){
            // sum near 0
            float mx=(float)(4.0*U01(rng));
            float mn=-mx; int d=(int)(rng()%25)-12;
            mn=bits2f((uint32_t)((int64_t)f2b(mn)+d));
            r=mx;g=mn;b=mn;
        } else {
            // tiny delta
            float mx=(float)(8.0*U01(rng)-4.0);
            int d=1+(int)(rng()%5000);
            float mn=bits2f((uint32_t)((int64_t)f2b(mx)-(mx>=0?d:-d)));
            if(mn>mx) std::swap(mx,mn);
            r=mx;g=mn;b=mn;
        }
        emit(r,g,b);
    }
    for(auto&s:out) std::printf("%s\n",s.c_str());
    std::fprintf(stderr,"tried=%ld kept=%zu\n",tried,out.size());
    return 0;
}

