#[inline]
fn cpp_max(a: f32, b: f32) -> f32 { if a < b { b } else { a } }
#[inline]
fn cpp_min(a: f32, b: f32) -> f32 { if b < a { b } else { a } }
#[inline]
pub fn rgb_max(r: f32, g: f32, b: f32) -> f32 { cpp_max(cpp_max(r, g), b) }
#[inline]
pub fn rgb_min(r: f32, g: f32, b: f32) -> f32 { cpp_min(cpp_min(r, g), b) }
#[inline]
pub fn hsl_l(max: f32, min: f32) -> f32 { (max + min) / 2.0f32 }
pub fn hsl_s(max: f32, min: f32) -> f32 {
    let delta = max - min;
    let l = hsl_l(max, min);
    if max == min { 0.0f32 } else if l <= 0.5f32 { delta / (max + min) } else { delta / (2.0f32 - max - min) }
}
